from pathlib import Path
p=Path('work/scanner.html');s=p.read_text(encoding='utf-8-sig')
markup='''<div class="upload-section"><div class="upload-heading">Upload Email File or Screenshot</div><input id="file-input" type="file" accept=".eml,.txt,.png,.jpg,.jpeg,text/plain,message/rfc822,image/png,image/jpeg" hidden aria-label="Choose an email file or screenshot"><div class="upload-drop" id="upload-drop"><button class="upload-browse" type="button" id="browse-button" data-command="browse" aria-describedby="upload-status"><span class="upload-icon"><svg class="icon"><use href="#i-file"/></svg></span><span><strong>Drag &amp; drop an email file (.eml, .txt) or screenshot image here, or <em>click to browse</em></strong><small>EML / TXT up to 2 MB · PNG / JPG up to 10 MB · Processed locally</small></span></button></div><div id="upload-status" class="upload-status" role="status" aria-live="polite"></div><div class="upload-card" id="upload-card" hidden><div class="upload-card-top"><div><div class="upload-file-name" id="upload-name"></div><div class="upload-file-details" id="upload-details"></div></div><button class="upload-remove" type="button" data-command="remove-upload" aria-label="Remove uploaded file">Remove</button></div><img class="upload-image" id="upload-image" alt="Uploaded screenshot for visual inspection" hidden><div class="upload-note" id="upload-note"></div></div></div>'''
assert '<div class="upload-section">' not in s
s=s.replace('<div class="field-head"><label for="body">',markup+'<div class="field-head"><label for="body">')
p.write_text(s,encoding='utf-8')
p=Path('work/bundle.py');s=p.read_text(encoding='utf-8-sig').replace("Path('work/engine.js').read_text(encoding='utf-8-sig')", "Path('work/engine.js').read_text(encoding='utf-8-sig')+'\\n'+Path('work/files-engine.js').read_text(encoding='utf-8-sig')")
p.write_text(s,encoding='utf-8')
